  AND?: InputMaybe<ResolvedDependencyFilter>;
  DISTINCT?: InputMaybe<Scalars['Boolean']['input']>;
  NOT?: InputMaybe<ResolvedDependencyFilter>;
  OR?: InputMaybe<ResolvedDependencyFilter>;
