/** Defines a utility call that can be invoked within the system. */
export type UtilCall = {
  __typename?: 'UtilCall';
  arguments?: Maybe<Array<ActionArgument>>;
  operation: Scalars['String']['output'];
};

/** Defines a utility call that can be invoked within the system. */
export type UtilCallInput = {
  /** Key-value arguments map compiled for the target utility call. */
  arguments?: InputMaybe<Array<ActionArgumentInput>>;
  /** The function called (`str.upper`), or in a callback the effect (`ui.copy`, `task.answer`). */
  operation: Scalars['String']['input'];
};

export type Validator = {
  __typename?: 'Validator';
  call: UtilCall;
  /** The full call tree as raw JSON, so deep trees are not truncated by fragment depth. */
  callJson: Scalars['JSONSerializable']['output'];
  dependencies?: Maybe<Array<Scalars['String']['output']>>;
  errorMessage?: Maybe<Scalars['String']['output']>;
  label?: Maybe<Scalars['String']['output']>;
  source?: Maybe<Scalars['String']['output']>;
};

/**
 *
 * A validator for a port. `call` is a pure blok UtilCall evaluated client-side against the
 * catalog; it must return a boolean meaning 'valid'. Other ports the call references must be
 * listed in `dependencies` (the authoritative subscription list); `value` refers to the port's
 * own value. Use the .. syntax when traversing the tree of ports.
 *
 */
export type ValidatorInput = {
  /** The pure blok UtilCall, evaluated client-side against the catalog, that validates the port value. It must return a boolean meaning 'valid'. Argument value_paths may only reference names listed in `dependencies`, plus `value` for the port's own value. */
  call: UtilCallInput;
  /** The form-field subscription list of the validator: the keys of the other ports whose values the call may reference. This list is authoritative: a value_path in the call may only reference these names (plus `value` for the port's own value). Use the .. syntax to traverse the tree of ports, e.g. 'foo..bar' for the child 'bar' of port 'foo'. */
  dependencies?: InputMaybe<Array<Scalars['String']['input']>>;
  /** The error message to display when the validation fails */
  errorMessage?: InputMaybe<Scalars['String']['input']>;
  /** An optional human-readable label for the validator. */
  label?: InputMaybe<Scalars['String']['input']>;
  /** The authoring expression the call was compiled from (informational; never parsed or validated by the server). */
  source?: InputMaybe<Scalars['String']['input']>;
};

/** A catalog's default widget for ports matching a kind and/or structure identifier. A UI applies it when a port has no explicit widget; an identifier match beats a kind match. */
export type WidgetDefault = {
  __typename?: 'WidgetDefault';
  identifier?: Maybe<Scalars['String']['output']>;
  kind?: Maybe<PortKind>;
  returnWidget?: Maybe<ReturnWidget>;
  widget?: Maybe<AssignWidget>;
};

/** A catalog's default widget for ports matching a kind and/or structure identifier. A UI applies it when a port has no explicit widget; an identifier match beats a kind match. */
export type WidgetDefaultInput = {
  /** Structure identifier the default applies to, e.g. '@mikro/image'. */
  identifier?: InputMaybe<Scalars['String']['input']>;
  /** Port kind the default applies to. With `identifier`, both must match. */
  kind?: InputMaybe<PortKind>;
  /** The return widget to render for matching return ports that declare no widget of their own. */
  returnWidget?: InputMaybe<ReturnWidgetInput>;
  /** The assign widget to render for matching argument ports that declare no widget of their own. */
  widget?: InputMaybe<AssignWidgetInput>;
};

/** A window that is calculated */
export type Window = {
  __typename?: 'Window';
  label?: Maybe<Scalars['String']['output']>;
  windowFunction: WindowFunction;
};

/** Aggregation computed over a tracked value within a window. */
export enum WindowFunction {
  Count = 'COUNT',
  First = 'FIRST',
  Last = 'LAST',
  Max = 'MAX',
  Mean = 'MEAN',
  Min = 'MIN',
  Std = 'STD',
  Sum = 'SUM'
}

/** A window that is calculated */
export type WindowInput = {
  /** An optional human-readable label for the window. */
  label?: InputMaybe<Scalars['String']['input']>;
  /** The aggregation to compute over the tracked value within the window. */
  windowFunction: WindowFunction;
};

/** A schedule of a wiregram: run an agent's interface on an interval or a cron line. */
export type WireScheduleInput = {
  /** The name of the agent whose action runs, as the importing organization sees it (e.g. 'kuvert'). */
  agent: Scalars['String']['input'];
  /** The args every run is assigned with. */
  args?: InputMaybe<Scalars['Args']['input']>;
  /** Run slots missed during downtime late, in order, instead of skipping them. */
  catchUp?: Scalars['Boolean']['input'];
  /** A five-field cron line, read in `timezone` (exclusive with interval_seconds). */
  cron?: InputMaybe<Scalars['String']['input']>;
  /** What the rule is for. */
  description?: InputMaybe<Scalars['String']['input']>;
  /** Whether the rule starts out enabled. An organization's own later switch is kept on re-import. */
  enabled?: Scalars['Boolean']['input'];
  /** The rule stops after this moment. */
  endsAt?: InputMaybe<Scalars['DateTime']['input']>;
  /** Create the runs as ephemeral tasks (housekeeping: retention may drop them early). */
  ephemeralRuns?: Scalars['Boolean']['input'];
  /** The interface of that agent to run (e.g. 'sync_all_mailboxes'). */
  interface: Scalars['String']['input'];
  /** Run every N seconds (exclusive with cron). */
  intervalSeconds?: InputMaybe<Scalars['Int']['input']>;
  /** What the document calls this rule. Unique among the document's rules of its kind; importing again updates the rule with this key. */
  key: Scalars['String']['input'];
  /** The rule stops once it created this many runs. */
  maxRuns?: InputMaybe<Scalars['Int']['input']>;
  /** A human-readable name. */
  name: Scalars['String']['input'];
  /** Whether a run may start while the previous one is open. */
  overlap?: ScheduleOverlap;
  /** The policy of every run the rule creates: ASK holds a child an agent asks for until a person approves it, AUTO runs it unattended. */
  policy?: TaskPolicy;
  /** The IANA zone the cron line is read in. */
  timezone?: Scalars['String']['input'];
};

/** A trigger of a wiregram: run an agent's interface when a service signals a matching object. */
export type WireTriggerInput = {
  /** The name of the agent whose action runs, as the importing organization sees it (e.g. 'kuvert'). */
  agent: Scalars['String']['input'];
  /** The args every run is assigned with. */
  args?: InputMaybe<Scalars['Args']['input']>;
  /** Extra descriptor conditions the signal must satisfy. */
  conditions?: InputMaybe<Array<RequiresInput>>;
  /** Fire at most once per object within this many seconds. */
  debounceSeconds?: InputMaybe<Scalars['Int']['input']>;
  /** What the rule is for. */
  description?: InputMaybe<Scalars['String']['input']>;
  /** Whether the rule starts out enabled. An organization's own later switch is kept on re-import. */
  enabled?: Scalars['Boolean']['input'];
  /** The rule stops after this moment. */
  endsAt?: InputMaybe<Scalars['DateTime']['input']>;
  /** The structure identifier it reacts to, e.g. @mikro/arraydataset. */
  identifier: Scalars['String']['input'];
  /** The interface of that agent to run (e.g. 'sync_all_mailboxes'). */
  interface: Scalars['String']['input'];
  /** What the document calls this rule. Unique among the document's rules of its kind; importing again updates the rule with this key. */
  key: Scalars['String']['input'];
  /** The signal kind it reacts to. */
  kind: SignalKind;
  /** The rule stops once it created this many runs. */
  maxRuns?: InputMaybe<Scalars['Int']['input']>;
  /** A human-readable name. */
  name: Scalars['String']['input'];
  /** The policy of every run the rule creates: ASK holds a child an agent asks for until a person approves it, AUTO runs it unattended. */
  policy?: TaskPolicy;
  /** The STRUCTURE argument that receives the signalled object. */
  port: Scalars['String']['input'];
};

/** An automation document an organization imported, and the owner of the schedules and triggers it created. */
export type Wiregram = {
  __typename?: 'Wiregram';
  /** Who imported it last; the runs of its rules are assigned as this identity. */
  caller: Caller;
  /** When it was first imported. */
  createdAt: Scalars['DateTime']['output'];
  /** What the document says it is for. */
  description?: Maybe<Scalars['String']['output']>;
  /** The document as it was last imported: importable as it is. */
  document: Scalars['AnyDefault']['output'];
  /** Unique ID of the wiregram. */
  id: Scalars['ID']['output'];
  /** What the document calls itself; importing the same key again updates this wiregram. */
  key: Scalars['String']['output'];
  /** Human-readable name. */
  name: Scalars['String']['output'];
  /** The schedules it owns. */
  schedules: Array<Schedule>;
  /** The triggers it owns. */
  triggers: Array<Trigger>;
  /** When it was last imported. */
  updatedAt: Scalars['DateTime']['output'];
};


/** An automation document an organization imported, and the owner of the schedules and triggers it created. */
export type WiregramSchedulesArgs = {
  filters?: InputMaybe<ScheduleFilter>;
  ordering?: Array<ScheduleOrder>;
  pagination?: InputMaybe<OffsetPaginationInput>;
};


/** An automation document an organization imported, and the owner of the schedules and triggers it created. */
export type WiregramTriggersArgs = {
  filters?: InputMaybe<TriggerFilter>;
  ordering?: Array<TriggerOrder>;
  pagination?: InputMaybe<OffsetPaginationInput>;
};

/** Identify a wiregram. */
export type WiregramIdInput = {
  id: Scalars['ID']['input'];
};

/** A wiregram: one document of automation. Importing it creates its schedules and triggers; importing the same key again brings them in line with the new document. */
export type WiregramInput = {
  /** What the document is for. */
  description?: InputMaybe<Scalars['String']['input']>;
  /** What the document calls itself. Importing the same key again updates what the earlier import created. */
  key: Scalars['String']['input'];
  /** A human-readable name. */
  name: Scalars['String']['input'];
  /** The schedules it wants. */
  schedules?: InputMaybe<Array<WireScheduleInput>>;
  /** The triggers it wants. */
  triggers?: InputMaybe<Array<WireTriggerInput>>;
};

export type _Entity = MediaStore | Session | User;

export type _Service = {
  __typename?: '_Service';
  sdl: Scalars['String']['output'];
};

